From 41024fbb0ab6fed1563aec6644370162dece701a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Higor=20Eur=C3=ADpedes?= <heuripedes@gmail.com>
Date: Tue, 3 Oct 2017 19:54:32 -0300
Subject: [PATCH] Fix conditional jump on uninitialized data

This fixes a bug introduced in 862cf481081f58e3961c6dc1430af67ac147f828

diff --git a/tasks/task_image.c b/tasks/task_image.c
index bae218960e..72b31d383a 100644
--- a/tasks/task_image.c
+++ b/tasks/task_image.c
@@ -322,6 +322,7 @@ bool task_push_image_load(const char *fullpath, retro_task_callback_t cb, void *
    image->status                     = IMAGE_STATUS_TRANSFER;
    image->is_blocking                = false;
    image->is_blocking_on_processing  = false;
+   image->is_finished                = false;
    image->processing_final_state     = 0;
    image->processing_pos_increment   = 0;
    image->pos_increment              = 0;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by a conditional jump that occurred on the `is_finished` variable of the `image` structure, which was not initialized before being used. This could lead to unpredictable behavior or crashes, as the program may attempt to evaluate a variable that holds an indeterminate value.

        Commit message:
        Fix conditional jump on uninitialized data

This fixes a bug introduced in 862cf481081f58e3961c6dc1430af67ac147f828  

        Patch:

 bool task_push_image_load(const char *fullpath, retro_task_callback_t cb, void *user_data)
 {
    nbio_handle_t             *nbio   = NULL;
    struct nbio_image_handle   *image = NULL;
    retro_task_t                   *t = (retro_task_t*)calloc(1, sizeof(*t));

    if (!t)
       goto error_msg;

    nbio                = (nbio_handle_t*)malloc(sizeof(*nbio));

    if (!nbio)
       goto error;

    nbio->type          = NBIO_TYPE_NONE;
    nbio->is_finished   = false;
    nbio->status        = NBIO_STATUS_INIT;
    nbio->pos_increment = 0;
    nbio->status_flags  = 0;
    nbio->data          = NULL;
    nbio->path          = strdup(fullpath);
    nbio->handle        = NULL;
    nbio->msg_queue     = NULL;
    nbio->cb            = &cb_nbio_image_menu_thumbnail;

    if (video_driver_supports_rgba())
       BIT32_SET(nbio->status_flags, NBIO_FLAG_IMAGE_SUPPORTS_RGBA);

    image              = (struct nbio_image_handle*)malloc(sizeof(*image));   
    if (!image)
       goto error;

    image->type                       = IMAGE_TYPE_NONE;
    image->status                     = IMAGE_STATUS_TRANSFER;
    image->is_blocking                = false;
    image->is_blocking_on_processing  = false;
+   image->is_finished                = false;
    image->processing_final_state     = 0;
    image->processing_pos_increment   = 0;
    image->pos_increment              = 0;
    image->size                       = 0;
    image->handle                     = NULL;

    image->ti.width                   = 0;
    image->ti.height                  = 0;
    image->ti.pixels                  = NULL;
    image->ti.supports_rgba           = false;

    if (strstr(fullpath, file_path_str(FILE_PATH_PNG_EXTENSION)))
    {
       nbio->type       = NBIO_TYPE_PNG;
       image->type      = IMAGE_TYPE_PNG;
    }
    else if (strstr(fullpath, file_path_str(FILE_PATH_JPEG_EXTENSION)) 
          || strstr(fullpath, file_path_str(FILE_PATH_JPG_EXTENSION)))
    {
       nbio->type       = NBIO_TYPE_JPEG;
       image->type      = IMAGE_TYPE_JPEG;
    }
    else if (strstr(fullpath, file_path_str(FILE_PATH_BMP_EXTENSION)))
    {
       nbio->type       = NBIO_TYPE_BMP;
       image->type      = IMAGE_TYPE_BMP;
    }
    else if (strstr(fullpath, file_path_str(FILE_PATH_TGA_EXTENSION)))
    {
       nbio->type       = NBIO_TYPE_TGA;
       image->type      = IMAGE_TYPE_TGA;
    }

    nbio->data          = (struct nbio_image_handle*)image;

    t->state           = nbio;
    t->handler         = task_file_load_handler;
    t->cleanup         = task_image_load_free;
    t->callback        = cb;
    t->user_data       = user_data;

    task_queue_push(t);

    return true;

 error:
    task_image_load_free(t);
    free(t);
    if (nbio)
    {
       if (!string_is_empty(nbio->path))
          free(nbio->path);
       free(nbio);
    }

 error_msg:
    RARCH_ERR("[image load] Failed to open '%s': %s.\n",
          fullpath, strerror(errno));

    return false;
 }
